function AutoFishPanelService.new(from)
    ---@type AutoFishPanelService
    local instance = AutoFishPanelService.New()
    instance.luaDialog = from
    instance.TransferTo = from.TransferTo

    instance._isEndAuto = false

    instance.autoFishingCo = nil
    instance.closeNodeCo = nil
    instance._fixCo = nil
    instance._autoFishFailedEvent = Events.AddListener("AutoFishFailed", Bind(instance, instance.OnAutoFishFailedHandler))

    instance.TransferTo = from.TransferTo
    for k, v in pairs(from) do
        instance[k]=v
    end
    SetButtonAction(instance.BtnAutoFish, Bind(instance, instance.OnClick))
    return instance
end

function AutoFishPanelService:OnAutoFishFailedHandler()
    self._isFailed = true
end

function AutoFishPanelService:KillCo()
    if self.closeNodeCo then
        cs_coroutine.stop(self.closeNodeCo)
        self.closeNodeCo = nil
    end
    if self.autoFishingCo then
        cs_coroutine.stop(self.autoFishingCo)
        self.autoFishingCo = nil
    end
    if self._fixCo then
        cs_coroutine.stop(self._fixCo)
        self._fixCo = nil
    end
    if self._autoFishFailedEvent then
        Events.RemoveListener("AutoFishFailed", self._autoFishFailedEvent)
        self._autoFishFailedEvent = nil
    end
end

function AutoFishPanelService:UpdateInfo()
    --self.isUnlockAuto = FishingUtils.IsUnlockAuto(self.placeId)
    self.isUnlockAuto = GameUtils.IsHavePrivilegeCard(1)

    self.isAutoing = FishingUtils.IsAutoing()
    self.status = 1
    if not self.isUnlockAuto then
        self.status = 3
    else
        if self.isAutoing then
            self.status = 2
        else
            self.status = 1
        end
    end
    CfUtils.SetUISwitchImage(self.ImgLight, self.status)
    CfUtils.SetUISwitchText(self.Text, self.isAutoing and 2 or 1)
    CfUtils.SetActive(self.LockNode, not self.isUnlockAuto)
    CfUtils.SetActive(self.BtnAutoFishEffect, self.isAutoing)
    CfUtils.SetActive(self.ImgSymbol, self.isUnlockAuto)
    CfUtils.SetActive(self.FishingUnderway, self.isAutoing)

    CfUtils.FillText(self.TextFrequency, localize("(剩余垂钓次数:_num_)", {_num_ = FishingUtils.GetRemainAutoNum()}))
end

function AutoFishPanelService:StartAutoFishing()
    if self.autoFishingCo then
        cs_coroutine.stop(self.autoFishingCo)
        self.autoFishingCo = nil
    end
    self.autoFishingCo = cs_coroutine.start(function()
        self:UpdateInfo()
        CS.UnityEngine.Time.timeScale = FishingUtils.GetAutoSpeed()
        local params = {
            isAuto = true
        }
        cs_coroutine.yield_return(1)
        self.TransferTo(EGoFishState.Casting, params)
        self.autoFishingCo = nil
    end)
end

function AutoFishPanelService:CanStartAutoFishing()
    CfUtils.StartCoroutineWithBlocker(function()
        if not FishingUtils.IsAutoing() then
            Events.Broadcast("CanStartAutoFishingReqEnd", {type = 0, errMsg = localize("已经开启了自动钓鱼")})
            return
        end

        if FishingUtils:GetRemainAutoNum() <= 0 then
            Events.Broadcast("CanStartAutoFishingReqEnd", {type=0, errMsg = ''})
            return
        end

        ---TODO
        self:CheckRod(function()
            local canFish, errMsg = self:IsCanFishIng()
            if not canFish then
                Events.Broadcast("CanStartAutoFishingReqEnd", {type = 0, errMsg = errMsg})
                return
            end

            if fishingComponent:GetIsAutoEnd() then
                Events.Broadcast("CanStartAutoFishingReqEnd", {type = 0, errMsg = ""})
                return
            end
            Events.Broadcast("CanStartAutoFishingReqEnd", {type = 1, errMsg=""})
        end)
    end)
end

--是否可以钓鱼
function AutoFishPanelService:IsCanFishIng()
    local err = ""
    local t = FishingUtils.GetFishingPropsList(self.placeId)
    for k, v in pairs(t) do
        local type = GoodsUtils.GetIdType(v)
        local dojo = FishingUtils.GetFishingGoodsDojo(v)
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(v)
        if dojo then
            if type == Constants.IDType.GoodsBait or type == Constants.IDType.GoodsFishingLine then
                if checkNumber(dojo.num) <= 0 then
                    if vo then
                        err = localize("_name_不足", {_name_ = vo.name})
                    end
                    return false, err
                end
            end
        else
            if vo then
                err = localize("_name_不足", {_name_ = vo.name})
            end
            return false, err
        end

        local limitPlaceId = FishingUtils.GetFishGoodsLimitPlaceData(v)
        --物品的限制条件
        if limitPlaceId > 0 then
            local isUnlock, err = FishingUtils.IsUnlockLimitDatas({
                {
                    limitId = ConstantsFishing.LimitType.FishPlace,
                    limitValue = limitPlaceId
                }
            }, {fishPlaceId = self.placeId})
            if not isUnlock then
                return false, vo.name..err
            end
        end
    end

    --渔场限制条件
    local t = FishingUtils.GetPlaceLimitInfo(self.placeId)
    local isUnlock, err = FishingUtils.IsUnlockLimitDatas(t, {fishPlaceId = self.placeId})
    if not isUnlock then
        return false, err
    end

    --判断钓鱼货币
    ---@type FishingPlaceVo
    local placeVo = FishingUtils.GetFishingPlaceVo(self.placeId)
    if placeVo then
        local goodsId = FishingUtils.GetCurUseCurrency(self.placeId, ConstantsFishing.ActivityType.Summer)
        if checkNumber(goodsId) <= 0 then
            return
        end

        local num = GoodsUtils.GetThingNo(goodsId)
        if num < checkNumber(placeVo.num) then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if vo then
                return false, localize("_name_不足", {_name_ = vo.name}), 1
            end
        end
    end
    return true, ""
end

function AutoFishPanelService:Reset()
    self.handExit = false
    self._isFailed = false
end

function AutoFishPanelService:ForceStop()
    fishingComponent:SetAutoing(false)
    fishingComponent:AutoFishEndReq(function()
        CS.UnityEngine.Time.timeScale = 1

        UIModule.OpenDialog({
            id = Constants.UITypeIds.UIFishPoolAutoSettlementDialog,
            parameters = {
                isHandExit = self.handExit,
                isNotEnough = self._notEnough,
                isFail = self._isFailed
            }
        },{
            {id = Constants.UITypeIds.UIFishPoolGoFishingDialog}
        })
        --self:UpdateInfo()
    end)

end





function AutoFishPanelService:ShowMe()
    self:UpdateInfo()
    CfUtils.SetActive(self.AutoFishNode, true)
end

function AutoFishPanelService:HideMe()
    CfUtils.SetActive(self.AutoFishNode, false)
end

function AutoFishPanelService:OnUpdate()
    if FishingUtils.IsAutoing() then
        local vo = FishingMgr:GetInstance():GetAutoTargetForceVo()
        if checkNumber(FishingMgr:GetInstance():GetCurForce()) <= (checkNumber(vo.maxWight) - checkNumber(vo.weight)) then
            FishingMgr:GetInstance():SetTieRod(true)
        elseif checkNumber(FishingMgr:GetInstance():GetCurForce()) >= (checkNumber(vo.maxWight)) then
            FishingMgr:GetInstance():SetTieRod(false)
        end
    end
end

function AutoFishPanelService:OnClick()
    local isAutoing = FishingUtils.IsAutoing()
    --自动中    中途月卡消失也能点退出
    if isAutoing then
        self.closeNodeCo = cs_coroutine.start(function()
            CfUtils.PlayAnimation(self.FishingUnderway.transform:Find("Layout"), "FishPoolGoFishingDialogTextTermination")
            cs_coroutine.yield_return(WaitForSeconds(0.5))
            CfUtils.SetActive(self.AutoFishNode, false)
            self.closeNodeCo = nil
        end)
        self._isEndAuto = true
        self.handExit = true
    else
        --local isUnlock = FishingUtils.IsUnlockAuto(self.placeId)
        local isHavePrivilege = GameUtils.IsHavePrivilegeCard(1)
        if not isHavePrivilege then
            --GameUtils.Toast(localize("当前渔场全图鉴解锁"))
            GameUtils.Toast(localize("特权卡解锁"))
            return
        end
        CfUtils.PlayAnimation(self.FishingUnderway.transform:Find("Layout"), "FishPoolGoFishingDialogTextIdle")

        --self.luaDialog.clearScene = true
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolAutoChooseFrequencyDialog, parameters = {fishPlaceId = self.placeId}}, {
            {id = Constants.UITypeIds.UIFishPoolGoFishingDialog}
        })
    end
end

function AutoFishPanelService:CheckRod(cb)
    local id = fishingComponent:GetCurEquipRodId(self.placeId)
    local vo = FishingUtils.GetFishingGoodsVoById(id)
    local dojo = FishingUtils.GetFishingGoodsDojo(id)
    --需要修
    if checkNumber(dojo.durability) == 0 then
        local isAutoFix = (checkNumber(KCookie.Get("FishAutoFix")) == 1)
        if isAutoFix then
            local consumeNum = FishingUtils.GetFixConsumeNum(id)
            local isCanFix = (GoodsUtils.GetThingNo(vo.fixCurrency) >= checkNumber(consumeNum))
            if not isCanFix then
                self._notEnough = true
                self:ForceStop()
            else
                fishingComponent:FishingFixReq(id, function()
                    self:CheckWheel(cb)
                end,function() 
                    self:ForceStop()
                end)
            end
        else
            self:ForceStop()
        end
    else
        self:CheckWheel(cb)
    end
end

function AutoFishPanelService:CheckWheel(cb)
    if self._fixCo then
        cs_coroutine.stop(self._fixCo)
        self._fixCo = nil
    end

    local id = fishingComponent:GetCurEquipReelId(self.placeId)
    local vo = FishingUtils.GetFishingGoodsVoById(id)
    local dojo = FishingUtils.GetFishingGoodsDojo(id)
    --需要修
    if checkNumber(dojo.durability) == 0 then
        local isAutoFix = (checkNumber(KCookie.Get("FishAutoFix")) == 1)
        if isAutoFix then
            local consumeNum = FishingUtils.GetFixConsumeNum(id)
            local isCanFix = (GoodsUtils.GetThingNo(vo.fixCurrency) >= checkNumber(consumeNum))

            self._fixCo = cs_coroutine.start(function()
                coroutine.yield(WaitForSeconds(1))
                if not isCanFix then
                    self._notEnough = true
                    self:ForceStop()
                else
                    fishingComponent:FishingFixReq(id, function()
                        if cb then
                            cb()
                        end
                    end, function()
                        self:ForceStop()
                    end)
                end
            end)
        else
            self:ForceStop()
        end
    else
        if cb then
            cb()
        end
    end
end

return AutoFishPanelService